  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਤਨਾਮ ਦੇ ਬੁਲਟ ਦੇ ਸੁਪਨੇ ਲੈਣ ਦੀ ਪ੍ਰਕਿਰਿਆ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ। ਇਹ ਕਿਵੇਂ ਦਰਸਾਉਂਦਾ ਹੈ ਕਿ ਬੱਚੇ ਕਿਵੇਂ ਸਿੱਖਦੇ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ 'ਜੋਸ਼' ਅਤੇ 'ਨਸ਼ੇ' ਵਿੱਚ ਕੀ ਅੰਤਰ ਹੈ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਬੱਚਿਆਂ ਦੀ ਖੁਸ਼ੀ ਅਤੇ ਮਾਪਿਆਂ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਦੇ ਟਕਰਾਅ ਨੂੰ ਕਿਵੇਂ ਦਰਸਾਇਆ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਕੋਈ ਨਵਾਂ ਡਰਾਮਾ ਹੋਣ ਵਾਲਾ ਹੈ' - ਇਸ ਵਾਕ ਤੋਂ ਪਿੰਡ ਦੇ ਲੋਕਾਂ ਦੀ ਮਾਨਸਿਕਤਾ ਬਾਰੇ ਕੀ ਪਤਾ ਲੱਗਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਬੁਲਟ ਚਲਾਉਣ ਦੇ ਢੰਗ ਨਾਲ ਵਾਤਾਵਰਣ ਅਤੇ ਆਵਾਜ਼ ਪ੍ਰਦੂਸ਼ਣ 'ਤੇ ਕੀ ਅਸਰ ਪੈਂਦਾ ਹੋਵੇਗਾ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੀ ਦਿਲਪ੍ਰੀਤ ਨੂੰ ਬੁਲਟ ਖਰੀਦਣ ਦੀ ਇਜਾਜ਼ਤ ਦੇਣਾ ਸਹੀ ਸੀ? ਆਪਣੇ ਜਵਾਬ ਦੇ ਹੱਕ ਵਿੱਚ ਤਰਕ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਤਨਾਮ ਦਾ 'ਹੋਰ ਤੇਜ਼ ਹੋਰ ਤੇਜ਼' ਕਹਿਣਾ ਦਿਲਪ੍ਰੀਤ 'ਤੇ ਕੀ ਅਸਰ ਪਾਉਂਦਾ ਹੋਵੇਗਾ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
