  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਤੋਂ ਸਾਨੂੰ ਕਿਹੜੀ ਨੈਤਿਕ ਸਿੱਖਿਆ ਮਿਲਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਮਾਪਿਆਂ ਦੀ ਬੱਚੇ ਪ੍ਰਤੀ ਮੁਹੱਬਤ ਨੂੰ ਤੁਸੀਂ ਕਿਹੜੀ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਰੱਖੋਗੇ - ਸਹੀ, ਗਲਤ ਜਾਂ ਅੰਨ੍ਹੀ? ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਵਰਣਿਤ ਘਟਨਾਵਾਂ ਨੂੰ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਬਿਆਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਲਟ ਮੋਟਰਸਾਈਕਲ ਦੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਦਾ ਜ਼ਿਕਰ ਕਰੋ ਜੋ ਪਾਠ ਵਿੱਚ ਦੱਸੀਆਂ ਗਈਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਦਿਲਪ੍ਰੀਤ ਨੂੰ ਬੁਲਟ ਨਾ ਮਿਲਦਾ ਤਾਂ ਉਸਦੇ ਅਤੇ ਸਤਨਾਮ ਦੇ ਸੁਭਾਅ 'ਤੇ ਕੀ ਅਸਰ ਪੈਂਦਾ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਦਿਲਪ੍ਰੀਤ ਦੇ ਕਿਰਦਾਰ ਚਿਤਰਨ ਬਾਰੇ ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ ਅਤੇ ਉਸਦੇ ਕੰਮਾਂ ਦੇ ਪ੍ਰਭਾਵਾਂ ਦੀ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦੇ ਪਾਤਰ ਦੀ ਉਸਾਰੀ ਕਰੋ। ਉਨ੍ਹਾਂ ਦੀ ਸਿਹਤ, ਪੇਸ਼ਾ ਅਤੇ ਘਟਨਾ ਦੌਰਾਨ ਉਨ੍ਹਾਂ ਦੀ ਹਾਲਤ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਾਜ਼ਾਰ ਵਿੱਚ ਵਾਪਰੀ ਘਟਨਾ ਦਾ ਵਿਸਥਾਰਪੂਰਵਕ ਵਰਣਨ ਕਰੋ। ਦਿਲਪ੍ਰੀਤ ਦੇ ਕੰਮ ਤੋਂ ਲੈ ਕੇ ਹਰਭਜਨ ਸਿੰਘ ਦੇ ਢੇਰੀ ਹੋਣ ਤੱਕ ਦੇ ਸਾਰੇ ਪਹਿਲੂਆਂ ਨੂੰ ਸ਼ਾਮਲ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਕੀ ਹੈ? ਜ਼ਿੰਦਗੀ ਦੀ ਅਨਿਸ਼ਚਿਤਤਾ ਅਤੇ ਮਨੁੱਖੀ ਵਿਵਹਾਰ ਦੇ ਪ੍ਰਭਾਵਾਂ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਟਨਾ ਤੋਂ ਬਾਅਦ ਬਾਜ਼ਾਰ ਵਿੱਚ ਲੋਕਾਂ ਦੀਆਂ ਪ੍ਰਤੀਕਿਰਿਆਵਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ। ਕਿਹੜੇ ਲੋਕ ਮਦਦ ਲਈ ਅੱਗੇ ਆਏ ਅਤੇ ਕਿਹੜੇ ਲੋਕਾਂ ਨੇ ਦੋਸ਼ ਲਾਇਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਲਟ ਦੇ ਪਟਾਕੇ ਮਾਰਨ ਵਰਗੀਆਂ ਗਤੀਵਿਧੀਆਂ ਸਮਾਜ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪਾਉਂਦੀਆਂ ਹਨ? ਇਸਦੇ ਸਕਾਰਾਤਮਕ ਅਤੇ ਨਕਾਰਾਤਮਕ ਪਹਿਲੂਆਂ 'ਤੇ ਚਾਨਣਾ ਪਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੇਖਕ ਦਾ ਇਸ ਪਾਠ ਨੂੰ ਲਿਖਣ ਦਾ ਕੀ ਉਦੇਸ਼ ਹੈ? ਪਾਠ ਵਿੱਚੋਂ ਉਦਾਹਰਣਾਂ ਦੇ ਕੇ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦੀ ਸਿਹਤ ਦੀ ਪਿਛਲੀ ਜਾਣਕਾਰੀ ਘਟਨਾ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ? ਇਸ ਨਾਲ ਪਾਠਕਾਂ ਦੀ ਹਮਦਰਦੀ ਕਿਵੇਂ ਵਧਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੇ ਬਿਆਨ 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ' ਦਾ ਕੀ ਭਾਵ ਹੈ? ਇਸ ਕਥਨ ਦੀ ਪ੍ਰਸੰਗ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਵਿੱਚੋਂ ਸਾਨੂੰ ਕਿਹੜੀਆਂ ਸਮਾਜਿਕ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਅਤੇ ਨੈਤਿਕ ਸਿੱਖਿਆਵਾਂ ਮਿਲਦੀਆਂ ਹਨ? ਵਿਸਥਾਰ ਨਾਲ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਤੁਸੀਂ ਇਸ ਘਟਨਾ ਦੇ ਗਵਾਹ ਹੁੰਦੇ, ਤਾਂ ਤੁਸੀਂ ਕੀ ਕਰਦੇ? ਆਪਣੀ ਪ੍ਰਤੀਕਿਰਿਆ ਅਤੇ ਕਾਰਵਾਈ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਵਰਤੀ ਗਈ ਭਾਸ਼ਾ ਸ਼ੈਲੀ ਅਤੇ ਸ਼ਬਦਾਵਲੀ ਬਾਰੇ ਚਰਚਾ ਕਰੋ। ਕੀ ਇਹ ਪਾਠਕਾਂ 'ਤੇ ਪ੍ਰਭਾਵ ਪਾਉਣ ਵਿੱਚ ਸਫਲ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
