  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਾਜ਼ਾਰ ਵਿੱਚ ਹੋਈ ਹਫੜਾ-ਦਫੜੀ ਅਤੇ ਲੋਕਾਂ ਦੇ ਇਕੱਠੇ ਹੋਣ ਦੇ ਦ੍ਰਿਸ਼ ਦਾ ਵਰਣਨ ਕਰੋ। ਇਸ ਨਾਲ ਮਾਹੌਲ ਕਿਵੇਂ ਬਦਲ ਗਿਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
