  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਦਿਲਪ੍ਰੀਤ ਨੇ ਪਟਾਕੇ ਨਾ ਮਾਰੇ ਹੁੰਦੇ ਤਾਂ ਕੀ ਘਟਨਾ ਵਾਪਰਦੀ? ਇਸਦੇ ਸੰਭਾਵੀ ਨਤੀਜਿਆਂ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਨੂੰ ਪੜ੍ਹਨ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੇ ਮਨ ਵਿੱਚ ਕਿਹੜੇ ਪ੍ਰਸ਼ਨ ਉੱਠਦੇ ਹਨ? ਕੋਈ ਤਿੰਨ ਪ੍ਰਸ਼ਨ ਲਿਖੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਸੰਭਾਵੀ ਉੱਤਰਾਂ ਬਾਰੇ ਸੋਚੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਵਰਤੇ ਗਏ ਮੁਹਾਵਰਿਆਂ ਅਤੇ ਅਖਾਣਾਂ (ਜਿਵੇਂ 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ') ਦੀ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਪ੍ਰਸੰਗਿਕਤਾ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੁਰਘਟਨਾ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਦੀ ਮਾਨਸਿਕ ਅਤੇ ਸਰੀਰਕ ਹਾਲਤ ਦਾ ਵਿਸਥਾਰਪੂਰਵਕ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਸਪਤਾਲ ਪਹੁੰਚਣ 'ਤੇ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਨੂੰ ਕਿਹੜੇ-ਕਿਹੜੇ ਡਰ ਸਤਾ ਰਹੇ ਸਨ? ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਮਨੋਵਿਗਿਆਨਕ ਪ੍ਰਭਾਵ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਦੇ ਮਾਪਿਆਂ ਦੀ ਹਸਪਤਾਲ ਵਿੱਚ ਪਹੁੰਚਣ 'ਤੇ ਕੀ ਪ੍ਰਤੀਕਿਰਿਆ ਸੀ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਹਾਲਤ ਕਿਹੋ ਜਿਹੀ ਸੀ? ਇਸ ਸਥਿਤੀ ਵਿੱਚ ਉਨ੍ਹਾਂ ਦੀਆਂ ਭਾਵਨਾਵਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੁਲਿਸ ਅਫਸਰ ਨੇ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਨੂੰ ਕੀ ਕਿਹਾ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਗਲਤੀ ਨੂੰ ਕਿਵੇਂ ਪਰਿਭਾਸ਼ਿਤ ਕੀਤਾ? ਇਸ ਕਥਨ ਦੇ ਸੰਭਾਵਿਤ ਪ੍ਰਭਾਵਾਂ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਮਨ ਵਿੱਚ ਕਿਹੜੀ ਆਵਾਜ਼ ਗੂੰਜ ਰਹੀ ਸੀ ਅਤੇ ਉਸਨੇ ਆਪਣੇ ਕੀਤੇ ਮਜ਼ਾਕ ਨੂੰ ਕਾਨੂੰਨ ਦੀ ਗੰਭੀਰ ਉਲੰਘਣਾ ਕਿਉਂ ਸਮਝਿਆ? ਵਿਸਥਾਰ ਵਿੱਚ ਸਮਝਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਸਪਤਾਲ ਵਿੱਚ ਹਰਭਜਨ ਸਿੰਘ ਦੇ ਇਲਾਜ ਲਈ ਕੀ ਤਿਆਰੀਆਂ ਕੀਤੀਆਂ ਗਈਆਂ ਅਤੇ ਡਾਕਟਰਾਂ ਦੀਆਂ ਹਦਾਇਤਾਂ ਤੋਂ ਸਥਿਤੀ ਦੀ ਗੰਭੀਰਤਾ ਕਿਵੇਂ ਪ੍ਰਤੀਤ ਹੁੰਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੁਲਿਸ ਦਾ ਹਸਪਤਾਲ ਆਉਣ ਦਾ ਮੁੱਖ ਉਦੇਸ਼ ਕੀ ਸੀ ਅਤੇ ਉਨ੍ਹਾਂ ਨੇ ਕਿਸ-ਕਿਸ ਦੇ ਬਿਆਨ ਦਰਜ ਕਰਨੇ ਸਨ? ਇਸ ਨਾਲ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪਿਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਬੁੱਲ੍ਹ ਸੁੱਕ ਰਹੇ ਸਨ' ਅਤੇ 'ਹੱਥ-ਪੈਰ ਫੁੱਲ ਗਏ' ਮੁਹਾਵਰਿਆਂ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋਏ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਦੀ ਡਰ ਵਾਲੀ ਸਥਿਤੀ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਸਪਤਾਲ ਦੇ ਮਾਹੌਲ ਨੇ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪਾਇਆ? ਉਨ੍ਹਾਂ ਨੂੰ ਕਿਉਂ ਲੱਗ ਰਿਹਾ ਸੀ ਕਿ ਹਰ ਕੋਈ ਉਨ੍ਹਾਂ ਦੇ ਘਿਨਾਉਣੇ ਕੰਮ ਦੀ ਨਿੰਦਾ ਕਰ ਰਿਹਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਬੱਜਰ ਗਲਤੀ' ਅਤੇ 'ਨਿੰਮੋਝੂਣੇ' ਸ਼ਬਦਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋਏ ਮਾਪਿਆਂ ਦੀ ਉਸ ਸਮੇਂ ਦੀ ਮਾਨਸਿਕ ਹਾਲਤ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ ਜਦੋਂ ਉਨ੍ਹਾਂ ਨੂੰ ਪੁੱਤਰਾਂ ਦੀ ਗਲਤੀ ਦਾ ਪਤਾ ਲੱਗਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦੀ ਸਿਹਤ ਦੀ ਗੰਭੀਰਤਾ ਬਾਰੇ ਡਾਕਟਰਾਂ ਦੀ ਗੱਲ ਸੁਣ ਕੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦੇ ਚਿਹਰੇ 'ਤੇ 'ਇੱਕ ਰੰਗ ਆਉਂਦਾ ਤੇ ਇੱਕ ਜਾਂਦਾ' ਸੀ। ਇਸ ਭਾਵਨਾਤਮਕ ਪ੍ਰਤੀਕਿਰਿਆ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਦੀ ਹਸਪਤਾਲ ਦੇ ਬੈਂਚ 'ਤੇ ਬੈਠਿਆਂ ਦੀ ਮਾਨਸਿਕ ਅਤੇ ਸਰੀਰਕ ਹਾਲਤ ਦਾ ਤੁਲਨਾਤਮਕ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਤਨਾਮ ਦੀ ਰੋਣਹਾਕੀ ਸ਼ਕਲ ਅਤੇ ਉਸਦੇ 'ਤੇਜ਼ ਰਫ਼ਤਾਰ ਅਤੇ ਪਟਾਕਿਆਂ ਵਾਲਾ ਸਿਰਜਿਆ ਭਰਮ ਟੁੱਟ ਗਿਆ ਹੋਵੇ' ਕਥਨ ਤੋਂ ਉਸਦੀ ਮਾਨਸਿਕ ਸਥਿਤੀ ਬਾਰੇ ਕੀ ਪਤਾ ਲੱਗਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਦਿਲਪ੍ਰੀਤ ਅਤੇ ਸਤਨਾਮ ਦੇ ਕਿਰਦਾਰਾਂ ਦੀ ਉਸਾਰੀ ਕਰੋ। ਉਨ੍ਹਾਂ ਦੀਆਂ ਗਲਤੀਆਂ ਅਤੇ ਪਛਤਾਵੇ ਨੂੰ ਉਜਾਗਰ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
