  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਜ਼ਿੰਮੇਵਾਰ ਨਾਗਰਿਕ' ਬਣਨ ਲਈ ਕਿਹੜੀਆਂ ਗੱਲਾਂ ਦਾ ਧਿਆਨ ਰੱਖਣਾ ਚਾਹੀਦਾ ਹੈ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਕਿਰਦਾਰ ਵਿੱਚ ਆਏ ਬਦਲਾਅ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਕੀ ਹੈ? ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ 'ਕਾਨੂੰਨੀ ਅਪਰਾਧ' ਸ਼ਬਦ ਦੀ ਵਰਤੋਂ ਕਿਉਂ ਕੀਤੀ ਗਈ ਹੈ? ਇਸਦੇ ਸਮਾਜਿਕ ਪ੍ਰਭਾਵਾਂ ਬਾਰੇ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਪਿਆਰ ਵਿੱਚ ਅੰਨ੍ਹੇ ਹੋਣਾ' ਵਾਕੰਸ਼ ਦਾ ਕੀ ਅਰਥ ਹੈ ਅਤੇ ਇਹ ਦਿਲਪ੍ਰੀਤ ਦੇ ਮਾਪਿਆਂ 'ਤੇ ਕਿਵੇਂ ਲਾਗੂ ਹੁੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਸਪਤਾਲ ਦਾ ਵਾਤਾਵਰਣ ਦਿਲਪ੍ਰੀਤ ਦੇ ਮਨ 'ਤੇ ਕਿਵੇਂ ਅਸਰ ਪਾਉਂਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਵਾਅਦੇ ਦੀ ਮਹੱਤਤਾ ਬਾਰੇ ਲਿਖੋ ਕਿ ਉਹ ਅਠਾਰਾਂ ਸਾਲਾਂ ਤੱਕ ਬੁਲਟ ਨਹੀਂ ਚਲਾਏਗਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਨੀਤੀਆਂ (NEP ਅਤੇ NCF) ਦਾ ਸਿੱਖਣ ਨਤੀਜਿਆਂ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪੈਂਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਾਹਨ ਚਲਾਉਂਦੇ ਸਮੇਂ ਦੂਜਿਆਂ ਦਾ ਖਿਆਲ ਰੱਖਣ ਬਾਰੇ ਜਾਗਰੂਕਤਾ ਕਿਵੇਂ ਵਧਾਈ ਜਾ ਸਕਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਛੋਟੀ ਜਿਹੀ ਗਲਤੀ ਕਿਵੇਂ ਕਿਸੇ ਦੀ ਜ਼ਿੰਦਗੀ ਬਰਬਾਦ ਕਰ ਸਕਦੀ ਹੈ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਉਦਾਹਰਨ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਪਿਤਾ ਦੇ ਸ਼ਬਦਾਂ "ਹੁਣ ਸਮਝ ਆਇਆ ਕਿ ਬੱਚਿਆਂ ਨੂੰ ਹਰ ਚੀਜ਼ ਦੇਣ ਨਾਲ ਉਹ ਵਧੇਰੇ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ, ਗੈਰ-ਜ਼ਿੰਮੇਵਾਰ ਬਣ ਜਾਂਦੇ ਹਨ" ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਤੋਂ ਤੁਸੀਂ ਸੜਕ ਸੁਰੱਖਿਆ ਬਾਰੇ ਕੀ ਸਿੱਖਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦੇ ਪਰਿਵਾਰ ਦੀ ਮਾਫ਼ੀ ਨੇ ਦਿਲਪ੍ਰੀਤ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪਾਇਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਵਾਅਦੇ ਨੂੰ 'ਉਮਰ ਭਰ ਪੱਲੇ ਬੰਨ੍ਹ ਕੇ ਰੱਖਣ' ਦਾ ਕੀ ਮਤਲਬ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਰਸਾਏ ਗਏ 'ਅਪਰਾਧ' ਦੇ ਸੰਕਲਪ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੜਕ 'ਤੇ ਚੱਲਦੇ ਹੋਏ ਸਾਨੂੰ ਕਿਹੜੀਆਂ ਸਾਵਧਾਨੀਆਂ ਵਰਤਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਕਹਾਣੀ ਸਮਾਜ ਨੂੰ ਕੀ ਸੰਦੇਸ਼ ਦਿੰਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('0fc4bcca-f8bd-4efa-b580-abfee761c826', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਿੰਡ ਦੀਆਂ ਗਲੀਆਂ ਵਿੱਚ ਜਦੋਂ ਵੀ ਦਿਲਪ੍ਰੀਤ ਦੇ ਬੁਲਟ ਮੋਟਰਸਾਈਕਲ ਦੀ ਦੁੱਗ-ਦੁੱਗ ਹੁੰਦੀ ਤਾਂ ਲੋਕ ਝੱਟ ਸਮਝ ਜਾਂਦੇ ਕਿ ਕੋਈ ਨਵਾਂ ਡਰਾਮਾ ਹੋਣ ਵਾਲਾ ਹੈ। ਗਿਆਰ੍ਹਵੀਂ ਜਮਾਤ ਵਿੱਚ ਪੜ੍ਹਨ ਵਾਲਾ ਦਿਲਪ੍ਰੀਤ ਪੜ੍ਹਾਈ ਵਿੱਚ ਤਾਂ ਦਰਮਿਆਨਾ ਸੀ ਪਰ ਬੁਲਟ ਦੀ ਰਫ਼ਤਾਰ ਅਤੇ ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕਿਆਂ ਵਿੱਚ ਉਸ ਦਾ ਜੋਸ਼ ਬਹੁਤਾ ਹੀ ਉਛਾਲੇ ਮਾਰਦਾ। ਉਸ ਦੀਆਂ ਨਸਾਂ ਵਿੱਚ ਬੁਲਟ ਦੀ ਤੇਜ਼ ਰਫ਼ਤਾਰ ਦਾ ਨਸ਼ਾ ਤੈਰਦਾ ਰਹਿੰਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('25870eca-509f-415b-9e53-960e62c79942', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਸਲ ਗੱਲ ਇਹ ਵੀ ਸੀ ਕਿ ਇਸ ਪਿੱਛੇ ਉਸ ਦੇ ਮਾਪਿਆਂ ਦਾ ਵੱਡਾ ਹੱਥ ਸੀ। ਉਹ ਦਿਲਪ੍ਰੀਤ ਦੀ ਹਰ ਛੋਟੀ ਤੋਂ ਛੋਟੀ ਖੁਸ਼ੀ ਉੱਤੇ ਫੁੱਲ ਚੜ੍ਹਾਉਂਦੇ। ਉਸ ਦੇ ਮੂੰਹੋਂ ਨਿਕਲਿਆ ਹਰ ਸ਼ਬਦ ਉਹਨਾਂ ਨੂੰ ਪ੍ਰਵਾਨ ਹੁੰਦਾ। ਜਦੋਂ ਉਸ ਨੇ ਘਰ ਵਿੱਚ ਬੁਲਟ ਦੀ ਫਰਮਾਇਸ਼ ਕੀਤੀ ਤਾਂ ਮੰਮੀ-ਪਾਪਾ ਨੇ ਬਿਨਾਂ ਕੁਝ ਸੋਚੇ-ਸਮਝੇ ਹੀ ਹਾਂ ਕਰ ਦਿੱਤੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('eab9205b-d06a-4f88-acc4-4ed2e0b31ab2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹਨਾਂ ਨੂੰ ਲੱਗਦਾ ਸੀ ਕਿ ਬੱਚੇ ਦੀ ਖੁਸ਼ੀ ਤੋਂ ਵੱਧ ਕੇ ਉਹਨਾਂ ਲਈ ਕੁਝ ਵੀ ਨਹੀਂ ਹੈ। ਕਿਸੇ ਨੇ ਵੀ ਇਹ ਨਹੀਂ ਸੋਚਿਆ ਕਿ ਇੱਕ ਨਾਬਾਲਗ ਦੇ ਹੱਥ ਵਿੱਚ ਤੇਜ਼ ਰਫ਼ਤਾਰ ਸਾਧਨ ਕਿਸੇ ਦਿਨ ਸਾਰਿਆਂ ਲਈ ਮੁਸੀਬਤ ਸਹੇੜ ਸਕਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('12eec1f6-b131-4712-a4ab-aee9a60fa58e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਚਾਚੇ ਦਾ ਪੁੱਤਰ ਸਤਨਾਮ ਭਾਵੇਂ ਅਜੇ ਅੱਠਵੀਂ ਵਿੱਚ ਹੀ ਪੜ੍ਹਦਾ ਸੀ ਪਰ ਉਹ ਦਿਲਪ੍ਰੀਤ ਵੱਲ ਵੇਖ ਕੇ ਹੁਣੇ ਤੋਂ ਹੀ ਬੁਲਟ ਦੇ ਸੁਪਨੇ ਲੈਣ ਲੱਗ ਪਿਆ ਸੀ। ਜਦੋਂ ਵੀ ਦਿਲਪ੍ਰੀਤ ਬੁਲਟ ਬਾਹਰ ਕੱਢਦਾ, ਸਤਨਾਮ ਭੱਜ ਕੇ ਉਸ ਦੇ ਪਿੱਛੇ ਚੜ੍ਹ ਜਾਂਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('857fd25c-fce1-42ac-a6ca-bb657d26bb0d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਨੂੰ ਗਲੀਆਂ ਅਤੇ ਸੜਕਾਂ ਉੱਤੇ ਤੇਜ਼ ਰਫ਼ਤਾਰ ਵਿੱਚ ਬੁਲਟ ਭਜਾਉਂਦਾ ਅਤੇ ਪਟਾਕਿਆਂ ਦੇ ਧਮਾਕੇ ਕਰਦਾ ਵੇਖ ਕੇ ਉਸ ਨੂੰ ਬੜਾ ਚਾਅ ਚੜ੍ਹਦਾ। ਉਹ ਦਿਲਪ੍ਰੀਤ ਨੂੰ 'ਹੋਰ ਤੇਜ਼ ਹੋਰ ਤੇਜ਼' ਕਹਿ ਕੇ ਸਪੀਡ ਵਧਵਾਉਂਦਾ ਜਾਂਦਾ। ਜਦੋਂ ਉਹ ਪਟਾਕੇ ਮਾਰਦੇ ਤਾਂ ਬੱਚੇ ਖਿੜ-ਖਿੜ ਕੇ ਹੱਸਦੇ। ਕੁਝ ਤਾੜੀਆਂ ਮਾਰਦੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cf079fb2-0732-431f-a7e5-39ab021f7d2b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('466a9600-4cb1-44b0-93c2-2dd110480625', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਾਜ਼ਾਰ ਲੋਕਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਸੀ। ਹਰ ਪਾਸੇ ਤਿਉਹਾਰਾਂ ਦੀ ਰੌਣਕ ਸੀ। ਦਿਲਪ੍ਰੀਤ ਨੇ ਆਪਣਾ ਬੁਲਟ ਗਲੀ ਵਿੱਚ ਭਜਾਇਆ। ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕੇ ਮਾਰ ਕੇ ਲੋਕਾਂ ਦਾ ਧਿਆਨ ਖਿੱਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ। ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b144f9b7-52d5-49ef-acd6-7413e679e01f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a553bed3-4122-4e86-9c72-66b1c2da5293', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ। ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('549e4745-a74f-41b6-9cf8-503ebbe73e59', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8a56607b-ac24-4407-93bc-d1d87b45d639', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ। ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।” ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ac8e4419-4255-4bd1-bd21-260776c9828c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e91973a0-19db-41e4-bb35-568dc1cebc08', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ। ਬਾਜ਼ਾਰ ਲੋਕਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਸੀ। ਹਰ ਪਾਸੇ ਤਿਉਹਾਰਾਂ ਦੀ ਰੌਣਕ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b312033a-77bc-4725-9f27-8a8ef29ef21f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਨੇ ਆਪਣਾ ਬੁਲਟ ਗਲੀ ਵਿੱਚ ਭਜਾਇਆ। ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕੇ ਮਾਰ ਕੇ ਲੋਕਾਂ ਦਾ ਧਿਆਨ ਖਿੱਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ। ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ। ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d0a56f08-cd36-4d5c-a220-4d9012a3c430', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ। ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e2605b40-2dea-4b4f-b302-4779211b925e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ। ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('df662b5a-ebad-4e2a-a3c2-abe5557f6184', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ। ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।” ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ। ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
