  ('8e92b1b2-9bfd-4e1e-a3de-3984506bef1e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ। ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ। ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ। ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5f4ddeae-2382-4a00-8745-ceb101b0fe5d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।” ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ। ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d9269e43-3985-4c4d-81da-11c3bbee1f68', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('50a4ccaf-b91f-4ae1-b404-135d0d43be63', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਾਜ਼ਾਰ ਲੋਕਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਸੀ। ਹਰ ਪਾਸੇ ਤਿਉਹਾਰਾਂ ਦੀ ਰੌਣਕ ਸੀ। ਦਿਲਪ੍ਰੀਤ ਨੇ ਆਪਣਾ ਬੁਲਟ ਗਲੀ ਵਿੱਚ ਭਜਾਇਆ। ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕੇ ਮਾਰ ਕੇ ਲੋਕਾਂ ਦਾ ਧਿਆਨ ਖਿੱਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ। ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4c081fb3-3117-4bf4-b917-e5bd4f159473', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ। ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
