  ('3df9bc15-7110-4e7a-9124-8bd2522c5299', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ। ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ। ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
