  ('9d9951e0-c33c-41ed-9d42-5dd1c05d3dbd', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
