  ('16556b8a-7ffb-4dc5-881c-4678a2e9d98a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ। ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('44457b9a-13dc-4205-a1dc-71f8d4018ca5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ। ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ। ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ। ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('27ecd4ac-31f4-4090-af25-3022b3426830', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ। ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
