  ('ea62ccc5-46bc-4e43-aa33-22d4a3ea2162', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('8afa442f-26bd-4361-9090-07d0845aea05', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਨੇ ਹਸਪਤਾਲ ਦੇ ਬਾਹਰ ਖੜ੍ਹੇ ਬੁਲਟ ਦੀ ਚਾਬੀ ਆਪਣੇ ਪਾਪਾ ਦੀ ਜੇਬ ਵਿੱਚ ਪਾ ਦਿੱਤੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('9bf796c5-fdec-41fa-b7ea-a2854c1ce7e1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਨੂੰ ਹੋਸ਼ ਆ ਗਈ। ਸਾਰਿਆਂ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c8755a07-9dd5-45f5-bdcc-4a7a4575df9b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਿੰਡ ਦੀਆਂ ਗਲੀਆਂ ਵਿੱਚ ਜਦੋਂ ਵੀ ਦਿਲਪ੍ਰੀਤ ਦੇ ਬੁਲਟ ਮੋਟਰਸਾਈਕਲ ਦੀ ਦੁੱਗ-ਦੁੱਗ ਹੁੰਦੀ ਤਾਂ ਲੋਕ ਝੱਟ ਸਮਝ ਜਾਂਦੇ ਕਿ ਕੋਈ ਨਵਾਂ ਡਰਾਮਾ ਹੋਣ ਵਾਲਾ ਹੈ। ਗਿਆਰ੍ਹਵੀਂ ਜਮਾਤ ਵਿੱਚ ਪੜ੍ਹਨ ਵਾਲਾ ਦਿਲਪ੍ਰੀਤ ਪੜ੍ਹਾਈ ਵਿੱਚ ਤਾਂ ਦਰਮਿਆਨਾ ਸੀ ਪਰ ਬੁਲਟ ਦੀ ਰਫ਼ਤਾਰ ਅਤੇ ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕਿਆਂ ਵਿੱਚ ਉਸ ਦਾ ਜੋਸ਼ ਬਹੁਤਾ ਹੀ ਉਛਾਲੇ ਮਾਰਦਾ। ਉਸ ਦੀਆਂ ਨਸਾਂ ਵਿੱਚ ਬੁਲਟ ਦੀ ਤੇਜ਼ ਰਫ਼ਤਾਰ ਦਾ ਨਸ਼ਾ ਤੈਰਦਾ ਰਹਿੰਦਾ। ਅਸਲ ਗੱਲ ਇਹ ਵੀ ਸੀ ਕਿ ਇਸ ਪਿੱਛੇ ਉਸ ਦੇ ਮਾਪਿਆਂ ਦਾ ਵੱਡਾ ਹੱਥ ਸੀ। ਉਹ ਦਿਲਪ੍ਰੀਤ ਦੀ ਹਰ ਛੋਟੀ ਤੋਂ ਛੋਟੀ ਖੁਸ਼ੀ ਉੱਤੇ ਫੁੱਲ ਚੜ੍ਹਾਉਂਦੇ। ਉਸ ਦੇ ਮੂੰਹੋਂ ਨਿਕਲਿਆ ਹਰ ਸ਼ਬਦ ਉਹਨਾਂ ਨੂੰ ਪ੍ਰਵਾਨ ਹੁੰਦਾ। ਜਦੋਂ ਉਸ ਨੇ ਘਰ ਵਿੱਚ ਬੁਲਟ ਦੀ ਫਰਮਾਇਸ਼ ਕੀਤੀ ਤਾਂ ਮੰਮੀ-ਪਾਪਾ ਨੇ ਬਿਨਾਂ ਕੁਝ ਸੋਚੇ-ਸਮਝੇ ਹੀ ਹਾਂ ਕਰ ਦਿੱਤੀ। ਉਹਨਾਂ ਨੂੰ ਲੱਗਦਾ ਸੀ ਕਿ ਬੱਚੇ ਦੀ ਖੁਸ਼ੀ ਤੋਂ ਵੱਧ ਕੇ ਉਹਨਾਂ ਲਈ ਕੁਝ ਵੀ ਨਹੀਂ ਹੈ। ਕਿਸੇ ਨੇ ਵੀ ਇਹ ਨਹੀਂ ਸੋਚਿਆ ਕਿ ਇੱਕ ਨਾਬਾਲਗ ਦੇ ਹੱਥ ਵਿੱਚ ਤੇਜ਼ ਰਫ਼ਤਾਰ ਸਾਧਨ ਕਿਸੇ ਦਿਨ ਸਾਰਿਆਂ ਲਈ ਮੁਸੀਬਤ ਸਹੇੜ ਸਕਦਾ ਹੈ। ਦਿਲਪ੍ਰੀਤ ਦੇ ਚਾਚੇ ਦਾ ਪੁੱਤਰ ਸਤਨਾਮ ਭਾਵੇਂ ਅਜੇ ਅੱਠਵੀਂ ਵਿੱਚ ਹੀ ਪੜ੍ਹਦਾ ਸੀ ਪਰ ਉਹ ਦਿਲਪ੍ਰੀਤ ਵੱਲ ਵੇਖ ਕੇ ਹੁਣੇ ਤੋਂ ਹੀ ਬੁਲਟ ਦੇ ਸੁਪਨੇ ਲੈਣ ਲੱਗ ਪਿਆ ਸੀ। ਜਦੋਂ ਵੀ ਦਿਲਪ੍ਰੀਤ ਬੁਲਟ ਬਾਹਰ ਕੱਢਦਾ, ਸਤਨਾਮ ਭੱਜ ਕੇ ਉਸ ਦੇ ਪਿੱਛੇ ਚੜ੍ਹ ਜਾਂਦਾ। ਦਿਲਪ੍ਰੀਤ ਨੂੰ ਗਲੀਆਂ ਅਤੇ ਸੜਕਾਂ ਉੱਤੇ ਤੇਜ਼ ਰਫ਼ਤਾਰ ਵਿੱਚ ਬੁਲਟ ਭਜਾਉਂਦਾ ਅਤੇ ਪਟਾਕਿਆਂ ਦੇ ਧਮਾਕੇ ਕਰਦਾ ਵੇਖ ਕੇ ਉਸ ਨੂੰ ਬੜਾ ਚਾਅ ਚੜ੍ਹਦਾ। ਉਹ ਦਿਲਪ੍ਰੀਤ ਨੂੰ 'ਹੋਰ ਤੇਜ਼ ਹੋਰ ਤੇਜ਼' ਕਹਿ ਕੇ ਸਪੀਡ ਵਧਵਾਉਂਦਾ ਜਾਂਦਾ। ਜਦੋਂ ਉਹ ਪਟਾਕੇ ਮਾਰਦੇ ਤਾਂ ਬੱਚੇ ਖਿੜ-ਖਿੜ ਕੇ ਹੱਸਦੇ। ਕੁਝ ਤਾੜੀਆਂ ਮਾਰਦੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 25, NULL),
  ('a4a83d40-5254-4c3a-b505-98b3e6bc0dfb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ। ਬਾਜ਼ਾਰ ਲੋਕਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਸੀ। ਹਰ ਪਾਸੇ ਤਿਉਹਾਰਾਂ ਦੀ ਰੌਣਕ ਸੀ। ਦਿਲਪ੍ਰੀਤ ਨੇ ਆਪਣਾ ਬੁਲਟ ਗਲੀ ਵਿੱਚ ਭਜਾਇਆ। ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕੇ ਮਾਰ ਕੇ ਲੋਕਾਂ ਦਾ ਧਿਆਨ ਖਿੱਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ। ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e6c5bcd2-3b11-4195-a873-8b750bd542b7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ। ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ। ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b3406bbb-a672-4fe6-ac72-3a2ed219f150', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ। ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ। ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।” ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ। ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9c29ce44-5c2b-43e5-93f9-cbd8c17b8b88', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ। ਬਾਜ਼ਾਰ ਲੋਕਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਸੀ। ਹਰ ਪਾਸੇ ਤਿਉਹਾਰਾਂ ਦੀ ਰੌਣਕ ਸੀ। ਦਿਲਪ੍ਰੀਤ ਨੇ ਆਪਣਾ ਬੁਲਟ ਗਲੀ ਵਿੱਚ ਭਜਾਇਆ। ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕੇ ਮਾਰ ਕੇ ਲੋਕਾਂ ਦਾ ਧਿਆਨ ਖਿੱਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ। ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ। ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e55bcac2-9b6f-4e79-a1c2-c151069aafe8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ। ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ। ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ। ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ। ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।” ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ। ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('603f6182-f61e-4728-8bcf-3670da99bd3c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਲਈ ਇਹ ਕੁਝ ਪਲਾਂ ਦਾ ਹਾਸਾ ਸੀ ਪਰ ਬਜ਼ੁਰਗਾਂ ਅਤੇ ਮਰੀਜ਼ਾਂ ਲਈ ਇਹ ਕਿਸੇ ਆਫਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਸੀ। ਜ਼ਿੰਦਗੀ ਦੇ ਰੰਗ ਹਮੇਸ਼ਾ ਇੱਕਸਾਰ ਨਹੀਂ ਰਹਿੰਦੇ। ਇੱਕ ਐਤਵਾਰ ਦੀ ਸ਼ਾਮ ਨੇ ਉਹ ਸਭ ਕੁਝ ਬਦਲ ਦਿੱਤਾ, ਜਿਸ ਉੱਤੇ ਦਿਲਪ੍ਰੀਤ ਮਾਣ ਕਰਦਾ ਸੀ। ਬਾਜ਼ਾਰ ਲੋਕਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਸੀ। ਹਰ ਪਾਸੇ ਤਿਉਹਾਰਾਂ ਦੀ ਰੌਣਕ ਸੀ। ਦਿਲਪ੍ਰੀਤ ਨੇ ਆਪਣਾ ਬੁਲਟ ਗਲੀ ਵਿੱਚ ਭਜਾਇਆ। ਸਾਈਲੈਂਸਰ ਦੇ ਪਟਾਕੇ ਮਾਰ ਕੇ ਲੋਕਾਂ ਦਾ ਧਿਆਨ ਖਿੱਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ। ਧਮਾਕਿਆਂ ਦੀ ਆਵਾਜ਼ ਅਚਾਨਕ ਹਾਸੇ, ਚੀਕਾਂ ਅਤੇ ਹਫੜਾ-ਦਫੜੀ ਵਿੱਚ ਬਦਲ ਗਈ। ਹੋਇਆ ਇੰਜ ਕਿ ਬਾਜ਼ਾਰ ਵਿੱਚ ਸੇਵਾਮੁਕਤ ਕਮਿਸ਼ਨਰ ਹਰਭਜਨ ਸਿੰਘ ਪੈਦਲ ਆਪਣੀ ਕਾਰ ਵੱਲ ਜਾ ਰਹੇ ਸਨ। ਉਹ ਕਈ ਸਾਲਾਂ ਤੋਂ ਦਿਲ ਦੀ ਬਿਮਾਰੀ ਤੋਂ ਪੀੜਤ ਸਨ ਅਤੇ ਸਰਜਰੀ ਤੋਂ ਬਾਅਦ ਬੜੀ ਮੁਸ਼ਕਲ ਨਾਲ ਸਿਹਤਯਾਬ ਹੋਏ ਸਨ। ਜਦੋਂ ਦਿਲਪ੍ਰੀਤ ਨੇ ਬੁਲਟ ਦਾ ਪਹਿਲਾ ਪਟਾਕਾ ਮਾਰਿਆ ਤਾਂ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਸਹਿ ਗਏ ਪਰ ਦੂਜੇ ਅਤੇ ਤੀਜੇ ਧਮਾਕੇ ਨੇ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਨੂੰ ਝੰਜੋੜ ਕੇ ਰੱਖ ਦਿੱਤਾ। ਉਹ ਇੱਕ ਪਾਸੇ ਢੇਰੀ ਹੋ ਗਏ। ਉਨ੍ਹਾਂ ਨਾਲ ਤੁਰੇ ਜਾਂਦੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰਾਂ ਦਾ ਚੀਕ-ਚਿਹਾੜਾ ਪੈ ਗਿਆ। ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਸਾਹ ਰੁਕਣ ਲੱਗਾ ਤੇ ਚਿਹਰੇ ਦਾ ਰੰਗ ਪੀਲਾ ਪੈਣ ਲੱਗਾ। ਲੋਕ ਇਕੱਠੇ ਹੋ ਗਏ। ਚੀਕਾਂ ਅਤੇ ਪਟਾਕਿਆਂ ਦੀ ਮਿੱਠੀ-ਜੁੜੀ ਆਵਾਜ਼ ਵਿੱਚ ਹਫੜਾ-ਦਫੜੀ ਦਾ ਅਜਿਹਾ ਦ੍ਰਿਸ਼ ਬਣਿਆ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਰੂਹ ਕੰਬ ਗਈ। ਇੰਨੇ ਵਿੱਚ ਇੱਕ ਆਟੋ-ਰਿਕਸ਼ਾ ਵਾਲੇ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਫਟਾਫਟ ਪਾਣੀ ਦਾ ਘੁੱਟ ਪਿਆਇਆ। ਭੀੜ ਵਿੱਚੋਂ ਇੱਕ ਸ਼ਖਸ ਬੋਲਿਆ, “ਇਹਨਾਂ ਨੂੰ ਦਿਲ ਦਾ ਦੌਰਾ ਪੈ ਗਿਆ ਹੈ। ਜਲਦੀ ਹਸਪਤਾਲ ਲੈ ਚੱਲੋ।” ਹਰਭਜਨ ਸਿੰਘ ਦਾ ਬੇਟਾ ਫਟਾਫਟ ਕਾਰ ਵੱਲ ਭੱਜ ਤੁਰਿਆ। ਭੀੜ ਵਿੱਚੋਂ ਮਨੀਰਾਮ ਦੁਕਾਨਦਾਰ ਦੀ ਆਵਾਜ਼ ਗੂੰਜੀ, “ਫੜੋ ਇਹਨਾਂ ਮੁਸ਼ਟੰਡਿਆਂ ਨੂੰ, ਕਰੋ ਪੁਲਿਸ ਹਵਾਲੇ। ਇਹ ਰੋਜ਼ ਇੰਜ ਹੀ ਕਰਦੇ ਆ, 'ਚਿੜੀਆਂ ਦੀ ਮੌਤ ਤੇ ਗਵਾਰਾਂ ਦਾ ਹਾਸਾ'।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
