  ('55b06921-da60-4a7d-9654-9b5bc7c68546', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਈਲੈਂਸਰ ਬਦਲ ਕੇ ਪਟਾਕੇ ਪਾਉਣਾ ਸਿਰਫ ਬਦਤਮੀਜ਼ੀ ਨਹੀਂ, ਬਲਕਿ ਕਾਨੂੰਨੀ ਅਪਰਾਧ ਵੀ ਹੈ। ਤੁਸੀਂ ਕਿਸੇ ਦੀ ਜਾਨ ਖਤਰੇ ਵਿੱਚ ਪਾਈ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('78f0deb7-fc0d-4927-abb1-a6f0892d8444', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਗੱਲ ਸੁਣਦਿਆਂ ਹੀ ਦਿਲਪ੍ਰੀਤ ਦੇ ਨਾਲ-ਨਾਲ ਉਹਨਾਂ ਦੇ ਮਾਪਿਆਂ ਦੀਆਂ ਅੱਖਾਂ ਵੀ ਝੁਕ ਗਈਆਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('130d264e-8812-44d7-917b-0fe40e8100fc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੇ ਪਿਤਾ ਨੇ ਠੰਡਾ ਸਾਹ ਲੈ ਕੇ ਆਖਿਆ, 'ਅਸੀਂ ਪਿਆਰ ਵਿੱਚ ਅੰਨ੍ਹੇ ਹੋ ਗਏ ਸੀ ਇੰਸਪੈਕਟਰ ਸਾਹਿਬ, ਹੁਣ ਸਮਝ ਆਇਆ ਕਿ ਬੱਚਿਆਂ ਨੂੰ ਹਰ ਚੀਜ਼ ਦੇਣ ਨਾਲ ਉਹ ਵਧੇਰੇ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ, ਗੈਰ-ਜ਼ਿੰਮੇਵਾਰ ਬਣ ਜਾਂਦੇ ਹਨ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('be535360-c379-4ec6-a73b-0b17e272d7bb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਸਪਤਾਲ ਵਿੱਚ ਚੱਲ ਰਹੀਆਂ ਮਸ਼ੀਨਾਂ ਦੀ ਬੀਪ ਵਿੱਚ ਦਿਲਪ੍ਰੀਤ ਨੂੰ ਮਹਿਸੂਸ ਹੋਇਆ ਕਿ ਇੱਕ ਛੋਟੀ ਜਿਹੀ ਗਲਤੀ ਕਿਵੇਂ ਕਿਸੇ ਦੀ ਜ਼ਿੰਦਗੀ ਨੂੰ ਬਰਬਾਦ ਕਰ ਸਕਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
