  ('0894cbe2-0c67-4a0d-9d6e-d1110e6e529f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲਪ੍ਰੀਤ ਦੀ ਗਲਤੀ ਮੰਨਣ ਉੱਤੇ ਹਰਭਜਨ ਸਿੰਘ ਦੇ ਪਰਿਵਾਰ ਨੇ ਉਹਨਾਂ ਨੂੰ ਮਾਫ਼ ਕਰ ਦਿੱਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d4ad986e-6f31-42c6-8b6e-1bfc15b1e703', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਗਲਤੀ ਤੋਂ ਬਾਅਦ ਦਿਲਪ੍ਰੀਤ ਨੇ ਇੱਕ ਹੋਰ ਵਧੀਆ ਕੰਮ ਕੀਤਾ। ਉਸਨੇ ਹਸਪਤਾਲ ਦੇ ਬਾਹਰ ਖੜ੍ਹੇ ਬੁਲਟ ਦੀ ਚਾਬੀ ਆਪਣੇ ਪਾਪਾ ਦੀ ਜੇਬ ਵਿੱਚ ਪਾ ਦਿੱਤੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6761e5d8-e138-4619-8ba2-aec5e08d4a4e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'de88171f-ab87-41c3-a091-20c256af8a75', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਤੇ ਵਾਅਦਾ ਕੀਤਾ ਕਿ ਇਹ ਬੁਲਟ ਉਦੋਂ ਤੱਕ ਮੇਰਾ ਨਹੀਂ ਜਦੋਂ ਤੱਕ ਮੈਂ ਅਠਾਰਾਂ ਸਾਲਾਂ ਦਾ ਨਹੀਂ ਹੋ ਜਾਂਦਾ। ਮੈਂ ਇਸ ਸਬਕ ਨੂੰ ਉਮਰ ਭਰ ਪੱਲੇ ਬੰਨ੍ਹ ਕੇ ਰੱਖਾਂਗਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-695Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
